from feal import f_function, g_function
import random

# Search for input diff D such that F(x) ^ F(x^D) == 0 for all x (prob 1)
# Test candidate D = 0x80808080
def test_D(D, trials=20000):
    for _ in range(trials):
        x = random.getrandbits(32)
        if f_function(x) ^ f_function(x ^ D) != 0:
            return False
    return True

for D in [0x80808080, 0x80808000, 0x80000000, 0x02020202, 0x80800000, 0x00000080, 0xFFFFFFFF, 0x80808080 ^ 0xFFFFFFFF]:
    print(hex(D), test_D(D, trials=5000))

# More general: compute distribution of output diff for random input diff?
# Let's brute force: for each D, estimate prob that outdiff==0
import collections
def prob_zero(D, trials=20000):
    c=0
    for _ in range(trials):
        x=random.getrandbits(32)
        if f_function(x)^f_function(x^D)==0:
            c+=1
    return c/trials

for D in [0x80808080, 0x02020202, 0x80800000, 0x80000080, 0x40404040]:
    print(hex(D), prob_zero(D, trials=5000))
