from feal import f_function
import random, collections

def out_diffs(D, trials=5000):
    c=collections.Counter()
    for _ in range(trials):
        x=random.getrandbits(32)
        d=f_function(x)^f_function(x^D)
        c[d]+=1
    return c.most_common(10), len(c)

for D in [0x80808080, 0x80808000, 0x02020202, 0x80808080]:
    mc, n = out_diffs(D)
    print(hex(D), [(hex(k),v) for k,v in mc], "distinct", n)

